        subMessage.style.cssText = 'font-size: 0.875rem; margin-top: 0.5rem;';
        subMessage.textContent = 'Capture your first document!';

        container.appendChild(icon);
        container.appendChild(message);
        container.appendChild(subMessage);

        return container;
    }

